-- Chi tra dong con giu dung gia tri script chinh da ghi (dong da sua sau do thi bo qua). Gia tri cu rong -> NULL.
-- Chay bang sqlcmd phai them -f 65001. Mac dinh ROLLBACK — doi soat xong moi doi sang COMMIT.

SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

DECLARE @tra TABLE (id_thiet_bi INT PRIMARY KEY,
    win_moi NVARCHAR(255) NOT NULL, office_moi NVARCHAR(255) NOT NULL, can_moi BIT NOT NULL,
    win_cu NVARCHAR(255) NOT NULL, office_cu NVARCHAR(255) NOT NULL, can_cu NVARCHAR(5) NOT NULL);

UPDATE tb SET tb.win_license = NULLIF(t.win_cu, N''), tb.office_license = NULLIF(t.office_cu, N''),
    tb.can_cai_office = CAST(NULLIF(t.can_cu, N'') AS BIT), tb.ngay_cap_nhat = GETDATE()
FROM KK_ThietBi tb JOIN @tra t ON t.id_thiet_bi = tb.id_thiet_bi
WHERE tb.win_license = t.win_moi AND tb.office_license = t.office_moi AND tb.can_cai_office = t.can_moi;
PRINT N'Đã trả lại ' + CAST(@@ROWCOUNT AS NVARCHAR(10)) + N' dòng';

ROLLBACK;
-- COMMIT;
